// Тикет #1cbe2254 · 1cbe2254766506dfd3839afc «תיקון QA: התאריך העברי ב«תאריכים חשובים» אינו לפי כלל השקיעה» — принят 13.10.2026 (iPhone, TestFlight 1.0.0 (19)).
// Кейс .qa/tests/important-dates/ID-05-hebrew-date-by-sunset.md. Факты 13.10 18:42 (закат 18:11): заголовок «ג׳ חשון תשפ״ז»;
//   день сегодня в календаре — label «2026-10-13, ב׳ חשון, מהשקיעה: ג׳ חשון» (до заката — без «מהשקיעה»);
//   «יישמר: 13.10.2026 · ג׳ חשון תשפ״ז — היום העברי שהתחיל בשקיעה»; в списке — бейдж «חשון» + «ג׳».
// AC: еврейская дата записи на сегодня = еврейской дате заголовка главной (сравниваются строки, не жёсткое «ג׳ חשון») — работает в любое время суток.
// @data: создаёт «QA-AUTO-שקיעה-NNNN», ID-05b удаляет (с 14.10 — проверка: #9bc6265b принят в сборке 20; раньше был skip).
// Окно «עריכת תאריך» заходит под строку статуса (#36a75b77) — «סגירה» только по элементу (label), не по координатам.
import { driver, expect } from '@wdio/globals';
import { byLabelStartsWith, byText, tapLabel, tapText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { dotDate, isoDate } from '../../../e2e/tests/_helpers/dates.ts';
import { skipWith } from '../_lib/app-0710.ts';
import {
  homeHebrewDate, homeDates, dateNameField, savedPreviewText, scrollToDateCard, badgeHasDayMonth,
  tryDeleteDate, closeEditDateWindow,
} from '../_lib/app-1310b.ts';

const NAME = `QA-AUTO-שקיעה-${String(Date.now()).slice(-4)}`;
let created = false;

describe('Важные даты — еврейская дата по закату (#1cbe2254)', () => {
  afterEach(async () => { await toHome().catch(() => {}); });

  it('ID-05 Запись на сегодня: еврейская дата = дате заголовка главной (до/после заката) #1cbe2254 @data', async function () {
    const now = new Date();
    const TODAY = isoDate(now);

    // 1. Заголовок главной: «<день> <месяц> <год>».
    const header = await homeHebrewDate();
    const headerDM = `${header.day} ${header.month}`;

    // 2. «הוספת תאריך חשוב» → «תאריך חשוב» → имя.
    await homeDates();
    await tapLabel('הוספת תאריך חשוב');
    await tapText('תאריך חשוב');
    const field = await dateNameField();
    await field.setValue(NAME);

    // 3. Календарь: день сегодня. После заката label «<iso>, <день>, מהשקיעה: <день заголовка>», до заката — «<iso>, <день заголовка>».
    const day = await byLabelStartsWith(`${TODAY}, `);
    await day.waitForDisplayed({ timeout: 15000 });
    const dayLabel = String((await day.getAttribute(driver.isAndroid ? 'content-desc' : 'label')) ?? '');
    const afterSunset = dayLabel.includes('מהשקיעה:');
    if (afterSunset) expect(dayLabel).toContain(`מהשקיעה: ${headerDM}`);
    else expect(dayLabel).toContain(`${TODAY}, ${headerDM}`);
    await day.click();

    // 4. «יישמר: DD.MM.YYYY · <дата заголовка>» (+ «— היום העברי שהתחיל בשקיעה» после заката).
    const preview = await savedPreviewText();
    expect(preview).toContain(`יישמר: ${dotDate(now)} · ${header.full}`);
    if (afterSunset) expect(preview).toContain('היום העברי שהתחיל בשקיעה');
    else expect(preview).not.toContain('היום העברי שהתחיל בשקיעה');

    // 5. «הוסף תאריך» → карточка «<имя>: פתיחה לעריכה», бейдж = месяц + день заголовка.
    await tapText('הוסף תאריך');
    await expect(byText('הוסף תאריך')).not.toBeDisplayed({ wait: 10000 });
    created = true;
    await homeDates();
    await scrollToDateCard(NAME);
    expect(await badgeHasDayMonth(NAME, header.day, header.month)).toBe(true);

    // Страховка: за время теста мог пройти закат (дата заголовка сменилась) — тогда результат не показателен.
    const after = await homeHebrewDate();
    if (after.full !== header.full) skipWith(this, `за время теста сменилась еврейская дата (${header.full} → ${after.full}) — закат во время теста, перезапустить`);
  });

  it('ID-05a Окно «עריכת תאריך» записи закрывается «סגירה» по элементу (#36a75b77) #1cbe2254 @prod-safe', async function () {
    if (!created) skipWith(this, 'запись ID-05 не создана');
    await homeDates();
    await (await scrollToDateCard(NAME)).click();
    await (await byText('עריכת תאריך')).waitForDisplayed({ timeout: 15000 });
    await closeEditDateWindow();
  });

  it('ID-05b Уборка: удалить «QA-AUTO-שקיעה-…» #1cbe2254 @data @cleanup', async function () {
    if (!created) skipWith(this, 'запись ID-05 не создана — убирать нечего');
    // 14.10: #9bc6265b исправлен (сборка 20) — удаление обязано работать; не удалилось → регресс #9bc6265b, убрать вручную.
    const gone = await tryDeleteDate(NAME);
    expect({ name: NAME, deleted: gone }).toEqual({ name: NAME, deleted: true });
  });
});
